$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'src/HousePrototype.psm1') -Force -DisableNameChecking
$s=New-HouseSession $PSScriptRoot 6001;if(@(Get-HouseVisibleIds $s)-contains'mail'){throw 'Mail was visible before the mailbox opened.'};$open=Invoke-HouseTurn $s 'open mailbox';if(-not$s.MailExposed-or@(Get-HouseVisibleIds $s)-notcontains'mail'){throw 'Opening mailbox did not expose mail.'};$mail=Invoke-HouseTurn $s 'look at the mail';if($mail.status-ne'resolved'-or$mail.clues_added-lt1){throw 'Mail clue was not reachable as its own object.'};$known=(@($s.State.Notebook.Clues.mail_accumulation.known_facts)-join' ');if($known-notmatch'addressed to Callum'){throw 'Mail lacks addressee.'}
$s=New-HouseSession $PSScriptRoot 6001;$assist=Invoke-HouseTurn $s 'ask Guillermo to inspect the mailbox';if(-not$s.MailExposed-or$assist.clues_added-lt1){throw 'Guillermo mailbox assistance did not preserve the established mail clue path.'}
$s=New-HouseSession $PSScriptRoot 6001;$rows=@('circle house','go cellar','dance with the chandelier'|ForEach-Object{Invoke-HouseTurn $s $_});$text=@($rows.narration)-join' ';if($text-match'\broute\b|Which connected room|visible route|Armand enters|cannot identify|yields no additional evidence'){throw "Engine voice reached house output: $text"}
Write-Host 'House voice/mail tests passed.'
